package dev.akhras;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.security.Principal;import java.util.*;import java.time.*;import java.math.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController public class Api{
 final Users users;final Refreshes refreshes;final Accounts accounts;final Expenses expenses;final Budgets budgets;final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder();
 Api(Users u,Refreshes r,Accounts a,Expenses e,Budgets b){users=u;refreshes=r;accounts=a;expenses=e;budgets=b;}
 record Credentials(@Email @NotBlank String email,@Size(min=8,max=100)String password){}
 Map<String,String>tokens(String id){String refresh=UUID.randomUUID()+"."+UUID.randomUUID();var r=new Domain.Refresh();r.hash=Tokens.digest(refresh);r.owner=id;r.expires=Instant.now().plusSeconds(30*86400);refreshes.save(r);return Map.of("accessToken",Tokens.issue(id),"refreshToken",refresh);}
 @PostMapping("/auth/register") @Transactional public Map<String,String>register(@Valid @RequestBody Credentials c){String email=c.email.toLowerCase(Locale.ROOT);if(users.findByEmail(email).isPresent())throw new IllegalArgumentException("email already registered");var u=new Domain.User();u.id=UUID.randomUUID().toString();u.email=email;u.password=passwords.encode(c.password);users.save(u);return tokens(u.id);}
 @PostMapping("/auth/login")public Map<String,String>login(@Valid @RequestBody Credentials c){var u=users.findByEmail(c.email.toLowerCase(Locale.ROOT)).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED));if(!passwords.matches(c.password,u.password))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED);return tokens(u.id);}
 @PostMapping("/auth/refresh") @Transactional public Map<String,String>refresh(@RequestBody Map<String,String>body){var r=refreshes.locked(Tokens.digest(body.getOrDefault("refreshToken",""))).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED));if(r.expires.isBefore(Instant.now()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED);String id=r.owner;refreshes.delete(r);refreshes.flush();return tokens(id);}
 @GetMapping("/accounts")public List<Domain.Account>accounts(Principal p){return accounts.findByOwner(p.getName());}
 @PostMapping("/accounts")public Domain.Account account(Principal p,@RequestBody Map<String,String>body){String name=body.getOrDefault("name","").trim();if(name.isEmpty())throw new IllegalArgumentException("name required");var a=new Domain.Account();a.owner=p.getName();a.name=name;return accounts.save(a);}
 @PostMapping("/expenses")public Domain.Expense add(Principal p,@RequestBody Domain.Expense e){accounts.findByIdAndOwner(e.accountId,p.getName()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));Domain.amount(e.amount);if(e.category==null||e.category.isBlank()||e.occurred==null)throw new IllegalArgumentException("category and date required");e.id=null;e.owner=p.getName();return expenses.save(e);}
 @GetMapping("/expenses")public List<Domain.Expense>expenses(Principal p,@RequestParam String month){var m=YearMonth.parse(month);return expenses.findByOwnerAndOccurredBetween(p.getName(),m.atDay(1),m.atEndOfMonth());}
 @PostMapping("/budgets")public Domain.Budget budget(Principal p,@RequestBody Domain.Budget b){YearMonth.parse(b.month);Domain.amount(b.amount);if(b.category==null||b.category.isBlank())throw new IllegalArgumentException("category required");b.id=null;b.owner=p.getName();return budgets.save(b);}
 @GetMapping("/summary")public List<Map<String,Object>>summary(Principal p,@RequestParam String month){var m=YearMonth.parse(month);var spent=new HashMap<String,BigDecimal>();for(var e:expenses.findByOwnerAndOccurredBetween(p.getName(),m.atDay(1),m.atEndOfMonth()))spent.merge(e.category,e.amount,BigDecimal::add);var limits=new HashMap<String,BigDecimal>();for(var b:budgets.findByOwnerAndMonth(p.getName(),month))limits.merge(b.category,b.amount,BigDecimal::add);var keys=new TreeSet<String>();keys.addAll(spent.keySet());keys.addAll(limits.keySet());var result=new ArrayList<Map<String,Object>>();for(String category:keys)result.add(Map.of("category",category,"spent",spent.getOrDefault(category,BigDecimal.ZERO),"budget",limits.getOrDefault(category,BigDecimal.ZERO)));return result;}
 @ExceptionHandler({IllegalArgumentException.class,java.time.format.DateTimeParseException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST)public Map<String,String>bad(Exception e){return Map.of("error",e.getMessage());}
}
